function setup() {
	createCanvas(windowWidth, windowHeight);
	background(20);
}

function draw() {
	let g=get()
	image(g, 0, 0, width, height*0.99)
	noFill()
	stroke(250)
	beginShape()
	for(let a=0; a<TAU; a+=TAU/200){
		let r= noise(sin(a), cos(a), frameCount/100)*height*0.333
		vertex(width/2+ sin(frameCount/100)*width/5+ sin(a)*r, height*0.666+cos(a)*r)
	}

	endShape()
}
